}

return items.map(item => ({
  json: {
    source: 'upload',
    mimeType: item.binary.data.mimeType || 'image/jpeg',
    fileName: item.binary.data.fileName || 'business-card.jpg'
  },
  binary: item.binary
}));

// Convert image to base64 for Vertex AI
const binaryData = items[0].binary?.data;

if (!binaryData || !binaryData.data) {
  throw new Error('No binary image data available');
}

// Get base64 data (remove data URL prefix if present)
let base64Data = binaryData.data;
if (typeof base64Data === 'string' && base64Data.includes('base64,')) {
  base64Data = base64Data.split('base64,')[1];
}

const mimeType = binaryData.mimeType || 'image/jpeg';

return [{
  json: {
    base64Image: base64Data,
    mimeType: mimeType,
    fileName: items[0].json?.fileName || 'image.jpg'
  },
  binary: items[0].binary
}];

