// Parse Vertex AI / Gemini response
const response = items[0].json;

let extracted = {
  name: null,
  company: null,
  title: null,
  email: null,
  phone: null,
  website: null,
  address: null,
  notes: null,
  confidence: 0,
  timestamp: new Date().toISOString()
};

try {
  // Vertex AI returns data in candidates[0].content.parts[0].text
  let contentText = '';

  if (response.candidates && response.candidates[0]) {
    const content = response.candidates[0].content;
    if (content && content.parts && content.parts[0]) {
      contentText = content.parts[0].text;
    }
  }

  if (!contentText) {
    throw new Error('No content returned from Vertex AI');
  }

  // Clean potential markdown formatting
  contentText = contentText.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

  // Parse JSON
  const parsedData = JSON.parse(contentText);

  // Map and validate fields
  extracted = {
    name: parsedData.name || null,
    company: parsedData.company || null,
    title: parsedData.title || null,
    email: parsedData.email || null,
    phone: parsedData.phone || null,
    website: parsedData.website || null,
    address: parsedData.address || null,
    notes: parsedData.notes || '',
    confidence: parsedData.confidence || 0.85,
    timestamp: new Date().toISOString()
  };

  // Basic validation flags
  extracted.has_email = !!extracted.email;
  extracted.has_phone = !!extracted.phone;
  extracted.has_company = !!extracted.company;

} catch (error) {
  console.error('Parse error:', error.message);
  extracted.notes = `Parsing fehlgeschlagen: ${error.message}`;
  extracted.confidence = 0.2;
  extracted.parse_error = true;
}

return [{ json: { extracted } }];

// Plausibility checks
const data = items[0].json.extracted;
const issues = [];
let score = 100;

// Email validation
if (data.email) {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
  if (!emailRegex.test(data.email)) {
    issues.push('❌ E-Mail-Format ungültig');
    data.email_valid = false;
    score -= 20;
  } else {
    data.email_valid = true;
  }
} else {
  issues.push('⚠️ Keine E-Mail gefunden');
  data.email_valid = false;
  score -= 15;
}

// Name validation
if (data.name) {
  const nameParts = data.name.trim().split(/\s+/);
  if (nameParts.length < 2) {
    issues.push('⚠️ Name eventuell unvollständig');
    data.name_valid = false;
    score -= 10;
  } else {
    data.name_valid = true;
  }
} else {
  issues.push('❌ Kein Name gefunden');
  data.name_valid = false;
  score -= 25;
}

// Phone validation
if (data.phone) {
  const phoneRegex = /[\d+\-\(\)\s]{7,}/;
  data.phone_valid = phoneRegex.test(data.phone);
  if (!data.phone_valid) {
    issues.push('⚠️ Telefonnummer Format prüfen');
    score -= 5;
  }
} else {
  data.phone_valid = false;
}

// Website validation
if (data.website) {
  try {
    // Add protocol if missing
    if (!data.website.startsWith('http')) {
      data.website = 'https://' + data.website;
    }
    new URL(data.website);
    data.website_valid = true;
  } catch {
    issues.push('⚠️ Website URL Format prüfen');
    data.website_valid = false;
    score -= 5;
  }
} else {
  data.website_valid = false;
}

// Company validation
if (!data.company) {
  issues.push('⚠️ Keine Firma gefunden');
  score -= 10;
}

// Overall plausibility
data.plausibility_score = Math.max(0, score);
data.plausible = score >= 60;
data.issues = issues;
data.quality = score >= 80 ? '✅ Sehr gut' : score >= 60 ? '⚠️ OK' : '❌ Niedrig';

return [{ json: { validated: data } }];

// Dedupe & Upsert Logic
const validated = items[0].json.validated;
const existingRows = items.slice(1).map(i => i.json);

function normalize(s) {
  if (!s) return '';
  return s.toLowerCase()
    .replace(/[^a-z0-9@.]/g, '')
    .trim();
}

const email = validated.email;
const name = normalize(validated.name);
const company = normalize(validated.company);

let foundRow = null;
let rowIndex = -1;

// Search for duplicate
for (let i = 0; i < existingRows.length; i++) {
  const row = existingRows[i];

  // Skip empty rows
  if (!row.name && !row.email) continue;

  const rowEmail = row.email;
  const rowName = normalize(row.name);
  const rowCompany = normalize(row.company);

  // Match by email (strongest match)
  if (email && rowEmail && normalize(email) === normalize(rowEmail)) {
    foundRow = row;
    rowIndex = i + 2; // +2 because: 1-indexed + header row
    break;
  }

  // Match by name + company (fallback)
  if (name && company && rowName && rowCompany) {
    const nameMatch = name === rowName;
    const companyMatch = company === rowCompany;

    if (nameMatch && companyMatch) {
      foundRow = row;
      rowIndex = i + 2;
      break;
    }
  }
}

const timestamp = new Date().toISOString();

if (foundRow) {
  // UPDATE - merge non-empty values
  const merged = {};

  for (const key of ['name', 'company', 'title', 'email', 'phone', 'website', 'address']) {
    // Prefer new value if old is empty/missing
    const oldVal = foundRow[key];
    const newVal = validated[key];

    if (newVal && newVal !== '') {
      merged[key] = newVal; // Always use new data if available
    } else if (oldVal && oldVal !== '') {
      merged[key] = oldVal; // Keep old if new is empty
    } else {
      merged[key] = '';
    }
  }

  // Merge notes
  const oldNotes = foundRow.notes || '';
  const newNotes = validated.notes || '';
  merged.notes = oldNotes ? `${oldNotes}\n---\n${newNotes} (${timestamp})` : newNotes;

  merged.last_updated = timestamp;
  merged.scan_count = (parseInt(foundRow.scan_count) || 0) + 1;

  return [{
    json: {
      action: 'update',
      data: merged,
      rowIndex: rowIndex,
      message: `Kontakt aktualisiert (Scan #${merged.scan_count})`
    }
  }];

} else {
  // CREATE new entry
  const newRow = {
    name: validated.name || '',
    company: validated.company || '',
    title: validated.title || '',
    email: validated.email || '',
    phone: validated.phone || '',
    website: validated.website || '',
    address: validated.address || '',
    notes: validated.notes || '',
    quality: validated.quality || '',
    plausibility_score: validated.plausibility_score || 0,
    created_at: timestamp,
    last_updated: timestamp,
    scan_count: 1
  };

  return [{
    json: {
      action: 'create',
      data: newRow,
      message: 'Neuer Kontakt erstellt'
    }
  }];
}

// Build final response
const sheetResult = items[0].json;
const dedupeInfo = items[1]?.json || {};

const response = {
  success: true,
  action: dedupeInfo.action || 'unknown',
  message: dedupeInfo.message || 'Erfolgreich verarbeitet',
  data: dedupeInfo.data || sheetResult,
  timestamp: new Date().toISOString(),
  table_url: 'https://n8n2.kortex-system.de/webhook/view-contacts'
};

return [{ json: response }];

// Generate HTML table view
const contacts = items.map(i => i.json);

const html = `
<!DOCTYPE html>
<html lang="de">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Kontakte - CRM</title>
    <style>
        * { margin: 0; padding: 0; box-sizing: border-box; }
        body {
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
            padding: 20px;
            min-height: 100vh;
        }
        .container {
            max-width: 1400px;
            margin: 0 auto;
            background: white;
            border-radius: 15px;
            box-shadow: 0 20px 60px rgba(0,0,0,0.3);
            padding: 30px;
        }
        h1 {
            color: #333;
            margin-bottom: 10px;
            font-size: 2em;
        }
        .stats {
            display: flex;
            gap: 20px;
            margin: 20px 0;
        }
        .stat-box {
            background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
            color: white;
            padding: 15px 25px;
            border-radius: 10px;
            font-weight: bold;
        }
        .table-wrapper {
            overflow-x: auto;
        }
        table {
            width: 100%;
            border-collapse: collapse;
            margin-top: 20px;
        }
        th, td {
            padding: 12px;
            text-align: left;
            border-bottom: 1px solid #e0e0e0;
        }
        th {
            background: #667eea;
            color: white;
            font-weight: 600;
            position: sticky;
            top: 0;
        }
        tr:hover {
            background: #f5f5f5;
        }
        .quality-badge {
            display: inline-block;
            padding: 4px 10px;
            border-radius: 12px;
            font-size: 0.85em;
            font-weight: 600;
        }
        .quality-good { background: #4caf50; color: white; }
        .quality-ok { background: #ff9800; color: white; }
        .quality-low { background: #f44336; color: white; }
        a { color: #667eea; text-decoration: none; }
        a:hover { text-decoration: underline; }
        .refresh-btn {
            background: #667eea;
            color: white;
            border: none;
            padding: 10px 20px;
            border-radius: 8px;
            cursor: pointer;
            font-size: 1em;
            margin: 10px 0;
        }
        .refresh-btn:hover { background: #764ba2; }
    </style>
</head>
<body>
    <div class="container">
        <h1>📇 Kontakte CRM</h1>
        <p style="color: #666; margin-bottom: 15px;">Automatisch erfasste Visitenkarten</p>

        <div class="stats">
            <div class="stat-box">📊 Gesamt: ${contacts.length}</div>
            <div class="stat-box">📧 Mit E-Mail: ${contacts.filter(c => c.email).length}</div>
            <div class="stat-box">📱 Mit Telefon: ${contacts.filter(c => c.phone).length}</div>
        </div>

        <button class="refresh-btn" onclick="location.reload()">🔄 Aktualisieren</button>

        <div class="table-wrapper">
            <table>
                <thead>
                    <tr>
                        <th>#</th>
                        <th>Name</th>
                        <th>Firma</th>
                        <th>Position</th>
                        <th>E-Mail</th>
                        <th>Telefon</th>
                        <th>Website</th>
                        <th>Qualität</th>
                        <th>Scans</th>
                        <th>Aktualisiert</th>
                    </tr>
                </thead>
                <tbody>
${contacts.map((c, idx) => `
                    <tr>
                        <td>${idx + 1}</td>
                        <td><strong>${c.name || '-'}</strong></td>
                        <td>${c.company || '-'}</td>
                        <td>${c.title || '-'}</td>
                        <td>${c.email ? `<a href="mailto:${c.email}">${c.email}</a>` : '-'}</td>
                        <td>${c.phone || '-'}</td>
                        <td>${c.website ? `<a href="${c.website}" target="_blank">🔗 Link</a>` : '-'}</td>
                        <td>${c.quality ? `<span class="quality-badge ${c.quality.includes('✅') ? 'quality-good' : c.quality.includes('⚠️') ? 'quality-ok' : 'quality-low'}">${c.quality}</span>` : '-'}</td>
                        <td>${c.scan_count || 1}</td>
                        <td>${c.last_updated ? new Date(c.last_updated).toLocaleString('de-DE') : '-'}</td>
                    </tr>
`).join('')}
                </tbody>
            </table>
        </div>

        <p style="margin-top: 20px; color: #999; font-size: 0.9em;">⏱️ Generiert: ${new Date().toLocaleString('de-DE')}</p>
    </div>
</body>
</html>
`;

return [{ json: { html } }];
